409	+package hotel.reservations;
410	+
411	+import hotel.rooms.RoomType;
412	+import java.math.BigDecimal;
413	+import java.time.DayOfWeek;
414	+import java.util.Map;
415	+
416	+/**
417	+ * The weekend package: in on Friday, out on the Sunday right after, exactly two nights, at a closed
418	+ * price all year round. Half of what was paid comes back on cancellation.
419	+ */
420	+final class WeekendPackagePlan implements RatePlanPolicy {
421	+
422	+    private static final int NIGHTS = 2;
423	+    private static final BigDecimal REFUNDED_SHARE = new BigDecimal("0.50");
424	+
425	+    /** The closed price of the package, which does not change with the season. */
426	+    private static final Map<RoomType, BigDecimal> PRICE_BY_ROOM_TYPE = Map.of(
427	+            RoomType.STANDARD, new BigDecimal("520.00"),
428	+            RoomType.DELUXE, new BigDecimal("820.00"),
429	+            RoomType.SUITE, new BigDecimal("1200.00"));
430	+
431	+    @Override
432	+    public void checkEligibility(Stay stay) {
433	+        if (stay.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY || stay.nights() != NIGHTS) {
434	+            throw new HotelException(
435	+                    ErrorCode.INVALID_REQUEST,
436	+                    "the weekend package goes from a Friday to the Sunday right after");
437	+        }
438	+    }
439	+
440	+    @Override
441	+    public Price price(Stay stay) {
442	+        BigDecimal packagePrice = PriceCalculator.cents(PRICE_BY_ROOM_TYPE.get(stay.room().type()));
443	+        return new Price(stay.nights(), packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
444	+    }
445	+
446	+    @Override
447	+    public BigDecimal refund(BigDecimal amountPaid) {
448	+        return PriceCalculator.cents(amountPaid.multiply(REFUNDED_SHARE));
449	+    }
450	+}
